    ('HEFRA-187', 'Ghana Atomic Energy Commission Hospital', 'OTHER', 'Greater Accra', 'Ga East Municipal', 'Kwabenya'),
    ('HEFRA-188', 'Ghana Infectious Disease Centre', 'OTHER', 'Greater Accra', 'Ga East Municipal', 'Kwabenya'),
    ('HEFRA-189', 'Volta River Authority Health Services Limited', 'OTHER', 'Western', 'Shama District', 'Aboadze')
) AS v(code, name, type, region, district, town)
JOIN "regions" r ON r."name" = v.region
JOIN "districts" d ON d."regionId" = r."id" AND d."name" = v.district
ON CONFLICT ("code") DO NOTHING;
